import{_ as o,o as e,c as a,ag as l}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"显现极乐念佛","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/念佛-显现极乐.md","filePath":"60-原文段落/念佛-显现极乐.md","lastUpdated":null}'),r={name:"60-原文段落/念佛-显现极乐.md"};function u(i,t,c,_,n,q){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="显现极乐念佛" tabindex="-1">显现极乐念佛 <a class="header-anchor" href="#显现极乐念佛" aria-label="Permalink to &quot;显现极乐念佛&quot;">​</a></h1><blockquote><p>来源：念佛法门与修心问答录（20090118）</p></blockquote><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><blockquote><p>&quot;你只管在心中默念南无阿弥陀佛，一字一句心里清清楚楚。这就是印光大师所说的&#39;心念耳闻&#39;。&quot;</p></blockquote><blockquote><p>&quot;显现你在极乐，调出这个开心、这个情景，有个抽象的感觉：&#39;我也在极乐，心情很好。&#39;然后也是默默地念佛，不要出声，在心中默默地念佛。念着念着睡着了就睡着了，明天起来的时候，记得你要起来的时候默默再念几句佛再起来也好，忘记了随便起来也算，没事了。&quot;</p></blockquote><blockquote><p>&quot;念佛是一边念一边发自内心向佛祖学习——诸恶莫作，众善奉行。&quot;</p></blockquote><blockquote><p>&quot;因为虽然念佛，体内内气到一定程度也会运行，什么大小周天也会有的。但是我们这些修炼方法，这个内气它是自动流转的，它好像血液循环一样，它没有什么地方开始，没有什么地方停止的。所以你收不收功都没关系。我们的收功只是好像平时打坐的时候，我有时候也叫人家要收功，反复默念&#39;我要收功了&#39;，这个是使我们的精神和身体从静态回到动态，起一个过渡、一个缓冲的作用。但是对于内气不用去管它。&quot;</p></blockquote><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点&quot;">​</a></h2><ul><li>念佛方法：心念耳闻——心中默念，每个字清清楚楚</li><li>核心心法：显现自己在极乐，调出开心的心情</li><li>卧式练法：躺着念佛，念着睡着就睡着，明早起来再念几句</li><li>内气自动流转，不必管收不收功</li></ul>',9)])])}const p=o(r,[["render",u]]);export{d as __pageData,p as default};
